//! OpenRouter model catalog ported from Pi's `packages/ai/src/providers/openrouter.models.ts`.
//!
//! Pi marks this catalog as generated by `scripts/generate-models.ts`; this Rust port
//! preserves the generated entries as checked in for this port row.

/// Pricing metadata for an OpenRouter model.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct OpenRouterModelCost {
    /// Input token price in Pi's model catalog units.
    pub input: f64,
    /// Output token price in Pi's model catalog units.
    pub output: f64,
    /// Cache-read token price in Pi's model catalog units.
    pub cache_read: f64,
    /// Cache-write token price in Pi's model catalog units.
    pub cache_write: f64,
}

/// OpenAI-compatible behavior overrides for an OpenRouter model.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct OpenRouterModelCompat {
    /// Whether OpenRouter should use OpenAI's `developer` role for this model.
    pub supports_developer_role: Option<bool>,
    /// Reasoning/thinking parameter format from Pi's compatibility metadata.
    pub thinking_format: Option<&'static str>,
    /// Prompt-cache control convention from Pi's compatibility metadata.
    pub cache_control_format: Option<&'static str>,
    /// Whether replayed assistant messages require an empty reasoning content field.
    pub requires_reasoning_content_on_assistant_messages: Option<bool>,
}

/// A `thinkingLevelMap` entry list from Pi's OpenRouter model catalog.
pub type OpenRouterThinkingLevelMap = &'static [(&'static str, Option<&'static str>)];

/// One OpenRouter model entry from Pi's generated model catalog.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct OpenRouterModel {
    /// Model id and catalog key.
    pub id: &'static str,
    /// Human-readable model name.
    pub name: &'static str,
    /// API implementation id.
    pub api: &'static str,
    /// Provider id.
    pub provider: &'static str,
    /// Base API URL.
    pub base_url: &'static str,
    /// OpenAI-compatible behavior overrides.
    pub compat: OpenRouterModelCompat,
    /// Whether the model supports reasoning.
    pub reasoning: bool,
    /// Optional Pi thinking-level mapping.
    pub thinking_level_map: Option<OpenRouterThinkingLevelMap>,
    /// Supported input modalities.
    pub input: &'static [&'static str],
    /// Model cost metadata.
    pub cost: OpenRouterModelCost,
    /// Context window in tokens.
    pub context_window: u32,
    /// Maximum output tokens.
    pub max_tokens: u32,
}

