#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn preserves_openrouter_catalog_metadata() {
        assert_eq!(OPENROUTER_MODELS.len(), 258);
        assert_eq!(OPENROUTER_MODELS[0].id, "ai21/jamba-large-1.7");
        assert_eq!(OPENROUTER_MODELS[0].cost.input, 2.0);
        assert_eq!(
            OPENROUTER_MODELS[0].compat.thinking_format,
            Some("openrouter")
        );
        assert_eq!(OPENROUTER_MODELS[12].thinking_level_map, Some(THINKING_1));
        assert_eq!(OPENROUTER_MODELS[257].id, "~openai/gpt-mini-latest");
        assert_eq!(OPENROUTER_MODELS[257].max_tokens, 128_000);
    }
}
